local card={api_version=1,id="UNG_942",name="Unite the Murlocs",text="[x]<b>Quest:</b> Summon\n8 Murlocs.\n<b>Reward:</b> Megafin.",set="UNGORO",type="spell",class="shaman",rarity="legendary",cost=1,keywords={"quest"}}
local function murloc(ctx,e) for _,t in ipairs(ctx:card_definition(ctx:entity(e).card_id).tags or {}) do if t=="murloc" or t=="all" then return true end end return false end
card.triggers={{event="minion_summoned",timing="after",active_zones={"secret"},condition=function(ctx,self,event) return event.player==ctx:controller(self) and murloc(ctx,event.entity) and ctx:get_data(self,"done")==0 end,effect=function(ctx,self) local n=ctx:get_data(self,"progress")+1; ctx:set_data(self,"progress",n); if n>=8 then ctx:set_data(self,"done",1);ctx:reveal_secret(self);ctx:give_card(ctx:controller(self),"UNG_942t") end end}}
local function receive(ctx,self,id) ctx:give_card(ctx:controller(self),id); ctx:continue_with("fill_murlocs") end
local function fill(ctx,self) local p=ctx:controller(self); if #ctx:hand(p)>=10 then return end local pool={} for _,id in ipairs(ctx:collectible_cards()) do for _,t in ipairs(ctx:card_definition(id).tags or {}) do if t=="murloc" or t=="all" then pool[#pool+1]=id;break end end end if #pool>0 then ctx:random_value(pool,"receive_murloc") end end
card.tokens={{id="UNG_942t",name="Megafin",text="<b>Battlecry:</b> Fill your hand with random Murlocs.",set="UNGORO",type="minion",class="shaman",collectible=false,cost=5,attack=8,health=8,tags={"murloc"},keywords={"battlecry"},on_battlecry=fill,fill_murlocs=fill,receive_murloc=receive}}
return card
